package org.telegram.messenger;

import android.media.*;
import java.io.*;
import java.nio.*;
import java.util.function.BooleanSupplier;

/** Prepare real native audio for an audio-capable model. No generated timing substitutes. */
public final class DevGramLyricsAudio {
 public static final int MAX_BYTES=12*1024*1024;
 public static final class Audio {public final byte[] bytes;public final String format;Audio(byte[] bytes,String format){this.bytes=bytes;this.format=format;}}
 public static Audio read(File file,BooleanSupplier cancelled)throws IOException{
  if(file==null||!file.isFile())throw new IOException("audio_unavailable");
  try(InputStream stream=new FileInputStream(file)){byte[] signature=new byte[12];int count=stream.read(signature);if(count>=3&&(signature[0]=='I'&&signature[1]=='D'&&signature[2]=='3'||(signature[0]&255)==255&&(signature[1]&224)==224&&(signature[1]&6)==2&&(signature[1]&24)!=8))return new Audio(bounded(file,cancelled),"mp3");if(count==12&&signature[0]=='R'&&signature[1]=='I'&&signature[2]=='F'&&signature[8]=='W'&&file.length()<=MAX_BYTES)return new Audio(bounded(file,cancelled),"wav");}
  MediaExtractor extractor=new MediaExtractor();MediaCodec codec=null;ByteArrayOutputStream pcm=new ByteArrayOutputStream();
  try{extractor.setDataSource(file.getPath());MediaFormat format=null;for(int i=0;i<extractor.getTrackCount();i++){MediaFormat candidate=extractor.getTrackFormat(i);String mime=candidate.getString(MediaFormat.KEY_MIME);if(mime!=null&&mime.startsWith("audio/")){format=candidate;extractor.selectTrack(i);break;}}if(format==null)throw new IOException("audio_track");codec=MediaCodec.createDecoderByType(format.getString(MediaFormat.KEY_MIME));codec.configure(format,null,null,0);codec.start();int rate=format.getInteger(MediaFormat.KEY_SAMPLE_RATE),channels=format.getInteger(MediaFormat.KEY_CHANNEL_COUNT);boolean inputEnd=false,outputEnd=false;long sourceFrames=0,outputFrames=0,deadline=System.nanoTime()+90_000_000_000L;MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();
   while(!outputEnd){if(cancelled.getAsBoolean()||Thread.currentThread().isInterrupted())throw new IOException("cancelled");if(System.nanoTime()>deadline)throw new IOException("audio_timeout");if(!inputEnd){int input=codec.dequeueInputBuffer(10000);if(input>=0){ByteBuffer bytes=codec.getInputBuffer(input);if(bytes==null)throw new IOException();int size=extractor.readSampleData(bytes,0);if(size<0){codec.queueInputBuffer(input,0,0,0,MediaCodec.BUFFER_FLAG_END_OF_STREAM);inputEnd=true;}else{codec.queueInputBuffer(input,0,size,Math.max(0,extractor.getSampleTime()),0);extractor.advance();}}}
    int index=codec.dequeueOutputBuffer(info,10000);if(index==MediaCodec.INFO_OUTPUT_FORMAT_CHANGED){MediaFormat actual=codec.getOutputFormat();rate=actual.getInteger(MediaFormat.KEY_SAMPLE_RATE);channels=actual.getInteger(MediaFormat.KEY_CHANNEL_COUNT);if(rate<=0||channels<1||channels>8||actual.containsKey("pcm-encoding")&&actual.getInteger("pcm-encoding")!=2)throw new IOException("audio_pcm");}else if(index>=0){ByteBuffer output=codec.getOutputBuffer(index);if(output!=null&&info.size>0){output.position(info.offset);output.limit(info.offset+info.size);output.order(ByteOrder.LITTLE_ENDIAN);while(output.remaining()>=channels*2){long sum=0;for(int channel=0;channel<channels;channel++)sum+=output.getShort();int mono=(int)(sum/channels);sourceFrames++;long until=sourceFrames*16000L/rate;while(outputFrames<until){pcm.write(mono&255);pcm.write(mono>>8&255);outputFrames++;if(pcm.size()>MAX_BYTES-44)throw new IOException("audio_too_large");}}}outputEnd=(info.flags&MediaCodec.BUFFER_FLAG_END_OF_STREAM)!=0;codec.releaseOutputBuffer(index,false);}}
   byte[] data=pcm.toByteArray();if(data.length==0)throw new IOException("audio_empty");ByteArrayOutputStream wav=new ByteArrayOutputStream(data.length+44);wav.write(new byte[]{'R','I','F','F'});little(wav,data.length+36,4);wav.write(new byte[]{'W','A','V','E','f','m','t',' '});little(wav,16,4);little(wav,1,2);little(wav,1,2);little(wav,16000,4);little(wav,32000,4);little(wav,2,2);little(wav,16,2);wav.write(new byte[]{'d','a','t','a'});little(wav,data.length,4);wav.write(data);return new Audio(wav.toByteArray(),"wav");
  }catch(Exception error){throw error instanceof IOException?(IOException)error:new IOException(error);}finally{extractor.release();if(codec!=null){try{codec.stop();}catch(Exception ignored){}codec.release();}}
 }
 private static void little(OutputStream stream,long value,int bytes)throws IOException{for(int i=0;i<bytes;i++)stream.write((int)(value>>(i*8))&255);}
 private static byte[] bounded(File file,BooleanSupplier cancelled)throws IOException{if(file.length()>MAX_BYTES)throw new IOException("audio_too_large");ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream input=new FileInputStream(file)){byte[] buffer=new byte[65536];int count;while((count=input.read(buffer))!=-1){if(cancelled.getAsBoolean()||bytes.size()+count>MAX_BYTES)throw new IOException("cancelled");bytes.write(buffer,0,count);}}return bytes.toByteArray();}
}
